function Get-NormalizedText { param([string]$Value) if($null -eq $Value){return ""}; return $Value.Trim().ToUpperInvariant() }; function Get-DeviceKey { param([string]$PartNumber,[string]$SerialNumber) $pn=Get-NormalizedText $PartNumber; $sn=Get-NormalizedText $SerialNumber; return "$pn|$sn" }; function Get-AssignmentKey { param([string]$PartNumber,[string]$SerialNumber,[string]$Derivat,[string]$IStufe) $pn=Get-NormalizedText $PartNumber; $sn=Get-NormalizedText $SerialNumber; $d=Get-NormalizedText $Derivat; $i=Get-NormalizedText $IStufe; return "$pn|$sn|$d|$i" }
function ConvertFrom-TrackingString { param([string]$InputString) $data=@{}; foreach($part in $InputString -split ";"){ if($part -match "="){ $kv=$part -split "=",2; $data[(Get-NormalizedText $kv[0])]=$kv[1].Trim() } }; [pscustomobject]@{PartNumber=$data["PN"];SerialNumber=$data["SN"];Hardware=$data["HW"];Software=$data["SW"]} }
function ConvertFrom-TrackingString { param([string]$InputString) $data=@{}; foreach($part in $InputString -split ";"){ if($part -match "="){ $kv=$part -split "=",2; $data[(Get-NormalizedText $kv[0])]=$kv[1].Trim() } }; [pscustomobject]@{PartNumber=$data["PN"];SerialNumber=$data["SN"];Hardware=$data["HW"];Software=$data["SW"]} }
function Get-DuplicateStatus { param([string]$ExistingDeviceKey,[string]$ExistingAssignmentKey,[string]$NewDeviceKey,[string]$NewAssignmentKey) if($ExistingAssignmentKey -eq $NewAssignmentKey){return "DUPLICATE"}; if($ExistingDeviceKey -eq $NewDeviceKey){return "DOUBLE_DERIVATIVE"}; return "NEW" }
function New-TrackingRecordClean { param([string]$LabelString,[string]$QRString,[string]$Derivat,[string]$IStufe,[string]$DuplicateStatus="NEW") $Label=ConvertFrom-TrackingString $LabelString; $QR=ConvertFrom-TrackingString $QRString; $DeviceKey=Get-DeviceKey -PartNumber $Label.PartNumber -SerialNumber $Label.SerialNumber; $AssignmentKey=Get-AssignmentKey -PartNumber $Label.PartNumber -SerialNumber $Label.SerialNumber -Derivat $Derivat -IStufe $IStufe; $MatchStatus=Test-TrackingMatch -Label $Label -QR $QR; if($MatchStatus -eq "LABEL_QR_MISMATCH"){$ValidationStatus="LABEL_QR_MISMATCH"}elseif($DuplicateStatus -eq "DUPLICATE"){$ValidationStatus="DUPLICATE"}elseif($DuplicateStatus -eq "DOUBLE_DERIVATIVE"){$ValidationStatus="DOUBLE_DERIVATIVE"}else{$ValidationStatus="OK"}; [pscustomobject]@{PartNumber=$Label.PartNumber;SerialNumber=$Label.SerialNumber;Derivat=(Get-NormalizedText $Derivat);IStufe=(Get-NormalizedText $IStufe);LabelHardware=$Label.Hardware;QRHardware=$QR.Hardware;LabelSoftware=$Label.Software;QRSoftware=$QR.Software;DeviceKey=$DeviceKey;AssignmentKey=$AssignmentKey;DuplicateStatus=$DuplicateStatus;ValidationStatus=$ValidationStatus;DoppelDerivat=($DuplicateStatus -eq "DOUBLE_DERIVATIVE")} }
function Save-TrackingRecordClean { param([pscustomobject]$Record,[switch]$DryRun) if($Record.DuplicateStatus -eq "DUPLICATE"){Write-Host "DUPLICATE: Datensatz wird nicht gespeichert:" $Record.AssignmentKey; return}; $Values=@{Title=$Record.AssignmentKey;DeviceKey=$Record.DeviceKey;AssignmentKey=$Record.AssignmentKey;PartNumber=$Record.PartNumber;SerialNumber=$Record.SerialNumber;Derivat=$Record.Derivat;IStufe=$Record.IStufe;LabelHardware=$Record.LabelHardware;QRHardware=$Record.QRHardware;LabelSoftware=$Record.LabelSoftware;QRSoftware=$Record.QRSoftware;ValidationStatus=$Record.ValidationStatus;DoppelDerivat=$Record.DoppelDerivat}; if($DryRun){Write-Host "[DRY-RUN] Datensatz würde gespeichert:" $Record.AssignmentKey; return}; Add-PnPListItem -List "Steuergeraete" -Values $Values | Out-Null; Write-Host "Datensatz gespeichert:" $Record.AssignmentKey }
function Test-TrackingMatch { param([pscustomobject]$Label,[pscustomobject]$QR) if((Get-NormalizedText $Label.PartNumber) -ne (Get-NormalizedText $QR.PartNumber)){return "LABEL_QR_MISMATCH"}; if((Get-NormalizedText $Label.SerialNumber) -ne (Get-NormalizedText $QR.SerialNumber)){return "LABEL_QR_MISMATCH"}; if((Get-NormalizedText $Label.Hardware) -ne (Get-NormalizedText $QR.Hardware)){return "LABEL_QR_MISMATCH"}; if((Get-NormalizedText $Label.Software) -ne (Get-NormalizedText $QR.Software)){return "LABEL_QR_MISMATCH"}; return "OK" }
